#!/usr/bin/env python3
"""Panel O11 reconstruit — installateur autonome.

Installe un panel web devant un o11pro existant. **Le binaire o11pro n'est
jamais touché** : ni modifié, ni déplacé, ni reconfiguré. Ses fichiers de
configuration et ses données non plus. Tout ce que cet installateur écrit tient
dans son propre répertoire, plus une unité systemd.

Le panel est servi par un petit relais qui garde tout ce qui appartient au
binaire — API, WebSocket, ressources embarquées, listes de lecture, lecture des
flux — et ne sert que l'interface.

    ./install-panel.py                       installe et démarre
    ./install-panel.py --port 8080           choisit le port d'écoute
    ./install-panel.py --upstream 1337       indique le port d'o11pro
    ./install-panel.py --prefix /opt/o11-panel
    ./install-panel.py --no-service          se contente de déposer les fichiers
    ./install-panel.py --uninstall           retire tout ce qu'il a posé
    ./install-panel.py --check               vérifie une installation existante
"""

import argparse
import base64
import hashlib
import io
import json
import os
import shutil
import socket
import subprocess
import sys
import tarfile
import time
import urllib.request

VERSION = "1.3.1"
SHA256 = "aa2c8e9cf674c537faafbe33e3e72b474bff20dcbb2a285f38d5eae02bbe36a4"
FICHIERS = 39
TAILLE = 382045
SERVICE = "o11-panel"

# Les routes de l'interface, telles que le routeur du panel les déclare.
# `--check` les parcourt TOUTES : n'en vérifier que deux laisserait passer un
# routage qui n'égare qu'un seul écran.
ROUTES_UI = (
    "/login", "/providers", "/provider/x/linear/config", "/linear/x", "/events/x",
    "/vod/x", "/recordings/x", "/epg/x", "/monitoring", "/logs/x", "/jobs",
    "/search", "/servers", "/users", "/help",
)

# La signature du panel d'origine. Si elle apparaît sur une route de
# l'interface, c'est o11pro qui répond à notre place.
SIGNATURE_ANCIEN = "OTT Streamer"

V, R, J, G = "\033[32m", "\033[31m", "\033[33m", "\033[0m"
if not sys.stdout.isatty():
    V = R = J = G = ""


def ok(m):
    print("  %s✓%s %s" % (V, G, m))


def ko(m):
    print("  %s✗%s %s" % (R, G, m))


def info(m):
    print("  %s·%s %s" % (J, G, m))


def echec(m):
    ko(m)
    sys.exit(1)


# ---------------------------------------------------------------- découverte
def ports_ecoutes():
    """Les ports TCP en écoute et LEUR ADRESSE, lus dans /proc — sans dépendre
    de `ss` ni de `netstat`, qui manquent sur bien des images minimales.

    L'adresse compte : un o11pro lié à une seule IP publique n'est pas joignable
    par 127.0.0.1, et resterait invisible."""
    trouves = {}
    for f, v6 in (("/proc/net/tcp", False), ("/proc/net/tcp6", True)):
        try:
            lignes = open(f).readlines()[1:]
        except OSError:
            continue
        for ligne in lignes:
            ch = ligne.split()
            if len(ch) <= 3 or ch[3] != "0A":  # 0A = LISTEN
                continue
            brut, port_hex = ch[1].split(":")
            port = int(port_hex, 16)
            if v6:
                adresse = "::"
            else:
                try:
                    adresse = socket.inet_ntoa(bytes.fromhex(brut)[::-1])
                except (ValueError, OSError):
                    continue
            trouves.setdefault(port, set()).add(adresse)
    return trouves


def adresses_a_tester(adresses):
    """Par où joindre un service : la boucle locale d'abord — c'est le chemin
    que le panel empruntera —, puis l'adresse réelle si elle est différente."""
    out = ["127.0.0.1"]
    for a in sorted(adresses):
        if a in ("0.0.0.0", "::", "127.0.0.1"):
            continue
        out.append(a)
    return out


def sonder(adresse, port, tls=False):
    """(verdict, détail) pour un service donné.

    Signature d'o11pro : un GET sur une ACTION d'API répond
    « 403 method not supported » — toute son API est en POST. Aucun autre
    serveur ne produit cette réponse par hasard.
    Attention : un GET sur `/api` tout court répond « 401 Unauthorized », ce qui
    ne distingue rien. Il faut viser une action réelle."""
    schema = "https" if tls else "http"
    hote = "[%s]" % adresse if ":" in adresse else adresse
    url = "%s://%s:%d/api/login" % (schema, hote, port)
    contexte = None
    if tls:
        import ssl
        contexte = ssl.create_default_context()
        contexte.check_hostname = False
        contexte.verify_mode = ssl.CERT_NONE
    try:
        with urllib.request.urlopen(url, timeout=4, context=contexte) as r:
            corps, code = r.read(300), r.status
    except urllib.error.HTTPError as e:
        try:
            corps, code = e.read(300), e.code
        except Exception:
            return "muet", "réponse illisible"
    except Exception as e:
        return "muet", type(e).__name__
    texte = corps.decode("utf-8", "replace")
    if "method not supported" in texte.lower():
        return "o11pro", schema
    # o11-rebuild : un autre logiciel, une autre API. On le reconnaît à sa MÉTA,
    # pas à son nom de processus (qui ne prouve rien) ni à son port (qui se
    # change). `api_version: v1` et la liste de ses modules ne se produisent pas
    # par hasard.
    # On n'accepte pas « un JSON a répondu » : `health` doit porter un statut ET
    # une version, ou `meta` une api_version v1 ET ses modules.
    for chemin, test in (
        ("/api/v1/health", lambda d: d.get("status") and d.get("version")),
        ("/api/v1/meta", lambda d: d.get("api_version") == "v1" and d.get("modules")),
    ):
        try:
            with urllib.request.urlopen(
                    "%s://%s:%d%s" % (schema, hote, port, chemin),
                    timeout=4, context=contexte) as r:
                d = json.loads(r.read(32000)).get("data") or {}
            if test(d):
                return "rebuild", "%s, version %s" % (schema, d.get("version", "?"))
        except Exception:
            continue
    return "autre", "code %s : %s" % (code, texte.strip().replace("\n", " ")[:60] or "corps vide")


def identite_rebuild(port, hote="127.0.0.1"):
    """Ce qu'o11-rebuild déclare : `/api/v1/health` d'abord, `/api/v1/meta` en
    repli. Ce sont les deux seules routes de son code qui portent une version,
    et les deux répondent sans session."""
    ident = {}
    for chemin, cles in (("/api/v1/health", ("version", "commit", "build_date", "status")),
                         ("/api/v1/meta", ("version", "api_version", "name"))):
        try:
            with urllib.request.urlopen(
                    "http://%s:%d%s" % (hote, port, chemin), timeout=4) as r:
                d = json.loads(r.read(32000)).get("data") or {}
        except Exception:
            continue
        for c in cles:
            if d.get(c) and not ident.get(c):
                ident[c] = d[c]
    return ident


def nature_amont(port, adresses=None):
    """« o11pro », « rebuild » ou None. Le panel sert les deux, mais pas de la
    même façon : le savoir AVANT d'écrire l'unité systemd évite une installation
    qui démarre puis ne répond à rien."""
    for a in adresses_a_tester(adresses or {"127.0.0.1"}):
        for tls in (False, True):
            v = sonder(a, port, tls)[0]
            if v in ("o11pro", "rebuild"):
                return v
    return None


def est_o11pro(port, adresses=None):
    return nature_amont(port, adresses) is not None


def inventaire():
    """Ce que la machine expose, et ce que chaque service a répondu. C'est ce
    qui permet de DIRE pourquoi rien n'a été trouvé, au lieu de le taire."""
    out = []
    for port, adresses in sorted(ports_ecoutes().items()):
        if not 80 <= port <= 65535:
            continue
        verdict, detail = "muet", ""
        for a in adresses_a_tester(adresses):
            for tls in (False, True):
                v, d = sonder(a, port, tls)
                if v in ("o11pro", "rebuild"):
                    verdict, detail = v, "%s via %s" % (d, a)
                    break
                if v == "autre" and verdict == "muet":
                    verdict, detail = v, d
            if verdict in ("o11pro", "rebuild"):
                break
        out.append((port, sorted(adresses), verdict, detail))
    return out


def chercher_amonts():
    """Les amonts trouvés, avec leur nature : [(port, "o11pro"|"rebuild")].

    Plusieurs peuvent tourner sur une même machine ; deviner laquelle servir
    serait présomptueux."""
    return [(p, v) for p, _, v, _ in inventaire() if v in ("o11pro", "rebuild")]


def chercher_o11pro():
    return [p for p, v in chercher_amonts()]


def libre(port):
    with socket.socket() as s:
        s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        try:
            s.bind(("0.0.0.0", port))
            return True
        except OSError:
            return False


# ---------------------------------------------------------------- opérations
def etat_chemin(prefix):
    return os.path.join(prefix, "etat.json")


def lire_etat(prefix):
    """Ce qu'une installation précédente a laissé. Sans ce fichier, on ne peut
    pas distinguer une première pose d'une mise à jour — et l'installateur
    annoncerait « installé » à quelqu'un qui vient de mettre à jour."""
    try:
        with open(etat_chemin(prefix)) as f:
            return json.load(f)
    except (OSError, ValueError):
        return None


def ecrire_etat(prefix, **champs):
    champs["date"] = time.strftime("%Y-%m-%dT%H:%M:%S%z")
    try:
        with open(etat_chemin(prefix), "w") as f:
            json.dump(champs, f, indent=1, sort_keys=True)
    except OSError:
        pass


def nature_operation(prefix):
    """(verbe, détail) — ce que cette exécution va réellement faire."""
    ancien = lire_etat(prefix)
    if not ancien:
        return "installation", ""
    av = ancien.get("version", "?")
    if ancien.get("archive") == SHA256:
        return "réinstallation", "version %s, contenu identique" % av
    if av != VERSION:
        return "mise à jour", "%s → %s" % (av, VERSION)
    return "mise à jour", "version %s, contenu modifié" % av


def deposer(prefix):
    charge = base64.b64decode(CHARGE)
    reel = hashlib.sha256(charge).hexdigest()
    if reel != SHA256:
        echec("archive corrompue (%s attendu, %s obtenu)" % (SHA256[:16], reel[:16]))
    ok("archive vérifiée — %s…" % SHA256[:16])

    # On remplace le panel précédent, jamais autre chose.
    ancien = os.path.join(prefix, "dist")
    if os.path.isdir(ancien):
        sauvegarde = ancien + ".precedent"
        shutil.rmtree(sauvegarde, ignore_errors=True)
        shutil.move(ancien, sauvegarde)
        info("panel précédent conservé dans %s" % sauvegarde)

    os.makedirs(prefix, exist_ok=True)
    with tarfile.open(fileobj=io.BytesIO(charge), mode="r:gz") as tar:
        for membre in tar.getmembers():
            cible = os.path.realpath(os.path.join(prefix, membre.name))
            if not cible.startswith(os.path.realpath(prefix)):
                echec("archive suspecte : %s" % membre.name)
        tar.extractall(prefix)
    os.chmod(os.path.join(prefix, "proxy-o11-panel.py"), 0o755)

    # L'installateur se copie lui-même : sans cela, « --check » et
    # « --uninstall » depuis /opt/o11-panel ne trouvent rien, alors que c'est
    # le chemin que la documentation indique.
    moi = os.path.abspath(sys.argv[0])
    cible = os.path.join(prefix, "install-panel.py")
    if os.path.isfile(moi) and os.path.realpath(moi) != os.path.realpath(cible):
        shutil.copyfile(moi, cible)
        os.chmod(cible, 0o755)
    ok("panel déposé dans %s (%d fichiers)" % (prefix, FICHIERS))


UNITE = """[Unit]
Description=Panel O11 reconstruit
Documentation=file://{prefix}/LISEZMOI.txt
After=network-online.target
Wants=network-online.target

[Service]
Type=simple
Environment=O11_PANEL_DIST={prefix}/dist
Environment=O11_UPSTREAM_HOST=127.0.0.1
Environment=O11_UPSTREAM_PORT={amont}
Environment=O11_UPSTREAM_KIND={nature}
Environment=O11_LISTEN_HOST={hote}
Environment=O11_LISTEN_PORT={port}
ExecStart=/usr/bin/env python3 {prefix}/proxy-o11-panel.py
Restart=on-failure
RestartSec=3
# Le panel n'a aucune raison d'écrire ailleurs que dans son répertoire.
ProtectSystem=strict
ProtectHome=yes
PrivateTmp=yes
NoNewPrivileges=yes
ReadOnlyPaths={prefix}

[Install]
WantedBy=multi-user.target
"""


def installer_service(prefix, amont, port, hote, nature="o11pro"):
    chemin = "/etc/systemd/system/%s.service" % SERVICE
    open(chemin, "w").write(UNITE.format(prefix=prefix, amont=amont, port=port,
                                         hote=hote, nature=nature))
    subprocess.run(["systemctl", "daemon-reload"], check=True)
    subprocess.run(["systemctl", "enable", SERVICE], check=True,
                   stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    subprocess.run(["systemctl", "restart", SERVICE], check=True)
    ok("service %s installé et démarré" % SERVICE)


def lire(url, methode="GET", corps=None, entetes=None, delai=4):
    req = urllib.request.Request(url, data=corps, method=methode, headers=entetes or {})
    try:
        with urllib.request.urlopen(req, timeout=delai) as r:
            return r.status, dict(r.headers), r.read(200000)
    except urllib.error.HTTPError as e:
        return e.code, dict(e.headers), e.read(200000)


def verifier(port, amont, service=True):
    """On ne dit « ça marche » qu'après l'avoir constaté — sur le service
    réellement installé, à travers une vraie socket HTTP."""
    base = "http://127.0.0.1:%d" % port
    echecs = 0

    if service:
        etat = subprocess.run(["systemctl", "is-active", SERVICE],
                              capture_output=True, text=True).stdout.strip()
        if etat == "active":
            ok("service %s actif" % SERVICE)
        else:
            ko("service %s : %s" % (SERVICE, etat or "absent"))
            echecs += 1

    for _ in range(20):
        try:
            code, _, coquille = lire(base + "/")
            break
        except Exception:
            time.sleep(0.5)
    else:
        ko("le panel ne répond pas sur le port %d" % port)
        return False

    texte = coquille.decode("utf-8", "replace")
    if SIGNATURE_ANCIEN in texte:
        ko("le port %d sert le panel D'ORIGINE — routage à revoir" % port)
        return False
    if "<div id=\"app\">" not in texte and "id=app" not in texte:
        ko("la coquille servie n'est pas celle du panel")
        echecs += 1
    else:
        ok("la coquille du panel répond")

    # Le bundle et la feuille de style. Leurs noms portent un HASH DE CONTENU
    # (`index-<hash>.js`) : on ne les devine pas, on les LIT dans la coquille
    # servie — c'est d'ailleurs le seul contrôle qui reste vrai d'un build à
    # l'autre.
    import re as _re
    refs = _re.findall(r'/static/assets/[^"\']+\.(?:js|css)', texte)
    if not refs:
        ko("la coquille ne référence aucun bundle")
        echecs += 1
    for chemin in refs:
        attendu = "javascript" if chemin.endswith(".js") else "css"
        minimum = 20000 if chemin.endswith(".js") else 500
        code, ent, corps = lire(base + chemin)
        t = ent.get("Content-Type", "")
        cache = ent.get("Cache-Control", "")
        if code == 200 and attendu in t and len(corps) >= minimum and "immutable" in cache:
            ok("%s servi immuable (%d octets, %s)" % (chemin, len(corps), t.split(";")[0]))
        else:
            ko("%s : code=%s type=%s taille=%d cache=%s" % (chemin, code, t, len(corps), cache))
            echecs += 1

    # TOUTES les routes de l'interface, pas deux.
    egarees = []
    for route in ROUTES_UI:
        try:
            code, ent, corps = lire(base + route)
        except Exception:
            egarees.append(route + " (injoignable)")
            continue
        t = corps.decode("utf-8", "replace")
        if code != 200 or "html" not in ent.get("Content-Type", ""):
            egarees.append("%s (code %s)" % (route, code))
        elif SIGNATURE_ANCIEN in t:
            egarees.append(route + " (panel D'ORIGINE)")
    if egarees:
        ko("routes de l'interface égarées : %s" % ", ".join(egarees))
        echecs += 1
    else:
        ok("les %d routes de l'interface restent au panel" % len(ROUTES_UI))

    # L'API doit répondre — relayée devant O11 Pro, traduite devant o11-rebuild.
    code, _, corps = lire(base + "/api/login", "POST", b"{}",
                          {"Content-Type": "application/json"})
    if code in (200, 400, 401, 403) and corps:
        ok("l'API répond (port amont %d)" % amont)
    else:
        ko("l'API ne répond pas (code %s)" % code)
        echecs += 1

    # Ce que le panel annonce pouvoir faire. C'est aussi la preuve de QUI est
    # derrière : le déclarer ici évite de vérifier une signature d'O11 Pro
    # devant un serveur qui n'en est pas un.
    try:
        code, _, corps = lire(base + "/__panel/capabilities")
        cap = json.loads(corps) if code == 200 else {}
    except Exception:
        cap = {}
    genre = cap.get("upstream_kind")
    if genre in ("o11pro", "rebuild"):
        ok("le panel annonce son amont : %s" % genre)
    else:
        ko("le panel n'annonce pas son amont")
        echecs += 1

    if genre == "rebuild":
        # Devant o11-rebuild, la preuve n'est pas une signature d'O11 Pro : c'est
        # que la couche traduit VRAIMENT — une route absente doit répondre 501
        # avec sa raison, jamais un succès vide.
        n = len(cap.get("routes_translated") or [])
        if n >= 20:
            ok("la couche de compatibilité traduit %d routes" % n)
        else:
            ko("la couche ne traduit que %d routes" % n)
            echecs += 1
        code, _, corps = lire(base + "/api/shutdown", "POST", b"{}",
                              {"Content-Type": "application/json"})
        if code == 501 and b"Message" in corps:
            ok("une route sans équivalent répond 501 avec sa raison")
        else:
            ko("une route sans équivalent ne se signale pas (code %s)" % code)
            echecs += 1
    else:
        # Un GET sur une action d'API porte la signature d'O11 Pro : c'est la
        # preuve que c'est bien LUI qui répond, et non notre repli SPA.
        code, _, corps = lire(base + "/api/login")
        if b"method not supported" in corps:
            ok("l'amont répond bien avec la signature d'O11 Pro")
        else:
            ko("l'amont ne répond pas comme un O11 Pro")
            echecs += 1

        # Les ressources du binaire passent, elles aussi.
        code, ent, _ = lire(base + "/static/o11-logo-white-transparent.svg")
        if code == 200 and "svg" in ent.get("Content-Type", ""):
            ok("les ressources embarquées d'O11 Pro sont relayées")
        else:
            ko("ressources d'O11 Pro non relayées (code %s)" % code)
            echecs += 1

    return echecs == 0


def desinstaller(prefix):
    chemin = "/etc/systemd/system/%s.service" % SERVICE
    if os.path.exists(chemin):
        subprocess.run(["systemctl", "disable", "--now", SERVICE],
                       stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        os.remove(chemin)
        subprocess.run(["systemctl", "daemon-reload"])
        ok("service retiré")
    if os.path.isdir(prefix):
        shutil.rmtree(prefix, ignore_errors=True)
        ok("%s supprimé" % prefix)
    info("o11pro n'a pas été touché.")


# ---------------------------------------------------------------- entrée
def afficher_inventaire(liste=None):
    """Ce que la machine écoute, et ce que chacun a répondu."""
    liste = liste if liste is not None else inventaire()
    if not liste:
        info("aucun port TCP en écoute n'a été trouvé dans /proc/net/tcp.")
        info("si le serveur tourne dans un conteneur, son port doit être publié.")
        return
    print("  Ports en écoute sur cette machine :")
    print("    %-7s %-22s %-9s %s" % ("PORT", "ADRESSE", "VERDICT", "RÉPONSE"))
    for port, adresses, verdict, detail in liste:
        marque = {"o11pro": V + "O11 Pro" + G,
                  "rebuild": V + "rebuild" + G,
                  "autre": "autre", "muet": "muet"}.get(verdict, verdict)
        # La marque de couleur occupe des octets invisibles : la colonne se cale
        # sur le texte, pas sur la chaîne.
        rembourrage = " " * max(0, 9 - len(verdict if verdict != "o11pro" else "O11 Pro"))
        print("    %-7d %-22s %s%s%s" % (port, ",".join(adresses)[:22],
                                         marque, rembourrage, detail[:52]))


def main():
    a = argparse.ArgumentParser(add_help=True, description="Panel O11 reconstruit")
    a.add_argument("--prefix", default="/opt/o11-panel")
    a.add_argument("--port", type=int, default=None, help="port d'écoute du panel")
    a.add_argument("--upstream", type=int, default=None, help="port d'o11pro")
    a.add_argument("--bind", "--host", dest="host", default="0.0.0.0",
                   help="adresse d'écoute du panel")
    a.add_argument("--yes", "-y", action="store_true",
                   help="ne pose aucune question (choisit un port libre si besoin)")
    a.add_argument("--no-service", action="store_true")
    a.add_argument("--uninstall", action="store_true")
    a.add_argument("--check", action="store_true")
    a.add_argument("--version", action="store_true")
    a.add_argument("--detect", action="store_true",
                   help="montre ce que la machine écoute, et ce que chacun répond")
    o = a.parse_args()

    if o.detect:
        print("\n  Panel O11 %s — détection\n" % VERSION)
        afficher_inventaire()
        print()
        return

    if o.version:
        print("o11-panel %s" % VERSION)
        print("archive %s" % SHA256)
        return

    verbe, detail = nature_operation(o.prefix)
    print("\n  Panel O11 reconstruit %s" % VERSION)
    if o.uninstall:
        print("  désinstallation\n")
    elif o.check:
        print("  vérification\n")
    else:
        print("  %s%s" % (verbe, (" — " + detail) if detail else ""))
        print("  %d fichiers, archive de %d octets\n" % (FICHIERS, TAILLE))

    if o.uninstall:
        if os.geteuid() != 0:
            echec("il faut être root pour désinstaller")
        desinstaller(o.prefix)
        return

    precedent = lire_etat(o.prefix) or {}
    amont = o.upstream or (precedent.get("upstream") if not o.uninstall else None)
    if amont and not o.upstream:
        info("amont repris de l'installation précédente : port %s" % amont)
    nature = precedent.get("upstream_kind") if not o.upstream else None
    if not amont:
        liste = inventaire()
        trouves = [(p, v) for p, _, v, _ in liste if v in ("o11pro", "rebuild")]
        if not trouves:
            ko("aucun serveur O11 trouvé en écoute sur cette machine.")
            print()
            afficher_inventaire(liste)
            print()
            info("Ce panel sert DEUX amonts : O11 Pro, et o11-rebuild.")
            info("Si l'un des deux tourne, indiquer son port :")
            print("      curl -fsSL <BASE>/install.sh | sudo sh -s -- --upstream <PORT>")
            info("Si aucun ne tourne, le panel n'a rien à servir.")
            sys.exit(2)
        if len(trouves) > 1:
            ko("plusieurs serveurs répondent : %s"
               % ", ".join("%d (%s)" % (p, v) for p, v in trouves))
            info("choisir lequel servir : ./install-panel.py --upstream %d" % trouves[0][0])
            sys.exit(2)
        amont, nature = trouves[0]
    elif nature_amont(amont) is None:
        ko("le port %d ne répond ni comme un O11 Pro ni comme un o11-rebuild." % amont)
        # Dire CE QU'ON A VU, pas seulement ce qu'on attendait : c'est la
        # différence entre « ça ne marche pas » et « voilà pourquoi ».
        verdict, detail = sonder("127.0.0.1", amont)
        if verdict == "muet":
            verdict, detail = sonder("127.0.0.1", amont, tls=True)
        info("attendu, pour O11 Pro    : « 403 method not supported » sur GET /api/login")
        info("attendu, pour o11-rebuild : api_version « v1 » sur GET /api/v1/meta")
        info("obtenu                    : %s" % (detail or "aucune réponse"))
        print()
        info("pour voir tout ce que la machine écoute :")
        print("      sudo python3 /opt/o11-panel/install-panel.py --detect")
        info("ou, sans rien installer :")
        print("      curl -fsSL <BASE>/install-panel.py -o /tmp/ip.py && python3 /tmp/ip.py --detect")
        sys.exit(2)
    if not nature:
        nature = nature_amont(amont) or "o11pro"
    if nature == "rebuild":
        ok("o11-rebuild détecté sur le port %d" % amont)
        # Ce que l'amont dit de LUI-MÊME. On ne lit ni fichier d'installation
        # (il vieillit sur place) ni octets du binaire : la seule source de
        # vérité est le processus qui répond.
        d = identite_rebuild(amont)
        if d:
            info("backend : O11 Rebuild")
            if d.get("name"):        info("nom     : %s" % d["name"])
            if d.get("version"):     info("version : %s" % d["version"])
            if d.get("api_version"): info("API     : %s" % d["api_version"])
            info("amont   : 127.0.0.1:%d" % amont)
        info("le panel passera par sa couche de compatibilité (voir docs/ADAPTER_MAP.md)")
        info("certaines fonctions n'existent pas derrière o11-rebuild ; les écrans le disent")
    else:
        ok("O11 Pro détecté sur le port %d" % amont)

    port = o.port or precedent.get("port") or (8080 if libre(8080) else 8081)
    if port == amont:
        echec("le panel ne peut pas écouter sur le port d'o11pro (%d)" % amont)
    if o.check:
        ancien = lire_etat(o.prefix)
        if ancien:
            info("installé : version %s, port %s, amont %s, le %s"
                 % (ancien.get("version", "?"), ancien.get("port", "?"),
                    ancien.get("upstream", "?"), ancien.get("date", "?")[:19]))
            if ancien.get("version") != VERSION:
                info("cet installateur porte la version %s — une mise à jour est disponible" % VERSION)
            port = o.port or ancien.get("port", port)
            amont = o.upstream or ancien.get("upstream", amont)
        sys.exit(0 if verifier(port, amont, service=True) else 1)

    # Une réinstallation n'est pas un conflit de port : si NOTRE service occupe
    # la place, on l'arrête — c'est le nôtre. Tout autre occupant est intouché.
    notre_unite = "/etc/systemd/system/%s.service" % SERVICE
    if not libre(port) and os.path.exists(notre_unite) and os.geteuid() == 0:
        actif = subprocess.run(["systemctl", "is-active", SERVICE],
                               capture_output=True, text=True).stdout.strip()
        if actif == "active":
            subprocess.run(["systemctl", "stop", SERVICE],
                           stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            for _ in range(20):
                if libre(port):
                    break
                time.sleep(0.25)
            info("panel déjà installé — réinstallation en cours")

    if not libre(port):
        # On ne tue jamais ce qui occupe le port, et on ne remplace aucun
        # service : c'est peut-être ce qui fait vivre la machine.
        if o.port is not None:
            ko("le port %d est déjà utilisé." % port)
            info("en choisir un autre : --port <libre>")
            sys.exit(2)
        libres = [p for p in range(8080, 8110) if p != amont and libre(p)]
        if not libres:
            echec("aucun port libre entre 8080 et 8110 — en indiquer un avec --port")
        if not o.yes:
            ko("le port %d est déjà utilisé." % port)
            info("relancer avec --port %d, ou --yes pour laisser choisir." % libres[0])
            sys.exit(2)
        port = libres[0]
        info("port %d occupé — le panel prendra le %d" % (o.port or 8080, port))

    if os.geteuid() != 0 and not o.no_service:
        echec("il faut être root (ou employer --no-service)")

    deposer(o.prefix)
    open(os.path.join(o.prefix, "LISEZMOI.txt"), "w").write(
        "Panel O11 reconstruit\n"
        "=====================\n\n"
        "Sert l'interface devant %s (port %d) sans toucher au serveur.\n\n"
        "  systemctl status %s\n"
        "  journalctl -u %s -f\n\n"
        "Désinstaller : ./install-panel.py --uninstall\n"
        "Le panel precedent, s'il y en avait un, est dans dist.precedent/\n"
        % ("o11-rebuild" if nature == "rebuild" else "O11 Pro", amont, SERVICE, SERVICE)
    )

    if o.no_service:
        info("fichiers déposés ; service non installé.")
        info("lancer à la main :")
        print("      O11_PANEL_DIST=%s/dist O11_UPSTREAM_PORT=%d O11_UPSTREAM_KIND=%s \\"
              % (o.prefix, amont, nature))
        print("        O11_LISTEN_PORT=%d \\" % port)
        print("        python3 %s/proxy-o11-panel.py" % o.prefix)
        return

    installer_service(o.prefix, amont, port, o.host, nature)
    print()
    if verifier(port, amont, service=True):
        ecrire_etat(o.prefix, version=VERSION, archive=SHA256, port=port,
                    upstream=amont, upstream_kind=nature, bind=o.host)
        titre = {"installation": "Le panel est installé",
                 "mise à jour": "Le panel est à jour",
                 "réinstallation": "Le panel est réinstallé"}[verbe]
        print("\n  %s%s :%s http://<cette-machine>:%d\n" % (V, titre, G, port))
        info("%s reste joignable comme avant sur le port %d."
             % ("o11-rebuild" if nature == "rebuild" else "O11 Pro", amont))
        if nature == "rebuild":
            print()
            info("Amont o11-rebuild : ce que le panel peut réellement faire est")
            info("annoncé sur http://<cette-machine>:%d/__panel/capabilities" % port)
    else:
        print("\n  %sInstallation incomplète.%s  journalctl -u %s -n 50\n" % (R, G, SERVICE))
        sys.exit(1)


CHARGE = ""

if __name__ == "__main__":
    main()
